def F(name,type,meaning,nullable=False,default='无',origin='source'):
 return dict(name=name,type=type,nullable=nullable,default=default,meaning=meaning,origin=origin)
def R(columns,target,target_columns=None,kind='proposed',cardinality='N:1',note=''):
 return dict(columns=['tenant_id']+columns,target=target,target_columns=['tenant_id']+(target_columns or ['id']),kind=kind,cardinality=cardinality,note=note)
