 tables.append(dict(name=name,schema='twinteams',status=status,title=title,purpose=purpose,source='database-design-v1.md · '+source,fields=[F('tenant_id','text','租户隔离键；所有主键、唯一键与关系均包含此列。')]+fields,primary_key=['tenant_id']+(pk or ['id']),constraints=constraints or [],indexes=indexes or [],relations=relations or []))
